            return False

        if generation != self.latest_running_generation:
            # Not the latest running generation
            return False

        if status not in ['queued', 'running']:
            # Invalid status for running generation
            return False

        # queued/running keep busy, no fetch needed
        if status in ['queued', 'running']:
